import { useEffect } from 'react'
import Svg, {
	Defs,
	G,
	LinearGradient,
	Path,
	Stop,
	Mask,
	Rect
} from 'react-native-svg'
import Animated, {
	Easing,
	Extrapolation,
	interpolate,
	SharedValue,
	useAnimatedProps,
	useAnimatedStyle,
	useSharedValue,
	withRepeat,
	withTiming
} from 'react-native-reanimated'

type CommonProps = {
	size?: number
	color?: string
	durationSec?: number
}

const APath = Animated.createAnimatedComponent(Path)
const AG = Animated.createAnimatedComponent(G)
const ALinearGradient = Animated.createAnimatedComponent(LinearGradient)

const useLoopT = (durationMs: number) => {
	const t = useSharedValue(0)
	useEffect(() => {
		t.set(
			withRepeat(
				withTiming(1, { duration: durationMs, easing: Easing.linear }),
				-1,
				false
			)
		)
	}, [durationMs, t])
	return t
}

const useOpacityTrack = (
	t: SharedValue<number>,
	times: number[],
	values: number[]
) =>
	useAnimatedProps(() => {
		return {
			opacity: interpolate(t.get(), times, values, Extrapolation.CLAMP)
		} as any
	})

const useDashReveal = (
	t: SharedValue<number>,
	times: number[],
	dashStart: number,
	dashEnd: number,
	fadeStart = 0.3,
	fadeEnd = 1
) =>
	useAnimatedProps(() => {
		const dash = interpolate(
			t.get(),
			times,
			[dashStart, dashStart, dashEnd, dashEnd],
			Extrapolation.CLAMP
		)
		const op = interpolate(
			t.get(),
			times,
			[fadeStart, fadeStart, fadeEnd, fadeEnd],
			Extrapolation.CLAMP
		)
		return { strokeDashoffset: dash, opacity: op } as any
	})

const useTranslateTrack = (
	t: SharedValue<number>,
	keyframes: [number, number, number][]
) =>
	useAnimatedProps(() => {
		const times = keyframes.map((k) => k[0])
		const xs = keyframes.map((k) => k[1])
		const ys = keyframes.map((k) => k[2])

		const tx = interpolate(t.get(), times, xs, Extrapolation.CLAMP)
		const ty = interpolate(t.get(), times, ys, Extrapolation.CLAMP)

		return { transform: `translate(${tx}, ${ty})` } as any
	})

const useRotateTrack = (t: SharedValue<number>) =>
	useAnimatedProps(() => {
		const deg = interpolate(t.get(), [0, 1], [0, 360], Extrapolation.EXTEND)
		return { transform: `rotate(${deg})` } as any
	})

